        normalized_key = _normalize_key(key)

        last_for_key = self._last_committed_for_key(normalized_key)
        if last_for_key is not None:
            committed_rid = last_for_key.get("id")
            if committed_rid == rid:
                replayed = dict(last_for_key)
                replayed["replayed"] = True
                replayed["committed"] = False
                return replayed
            raise ConflictError(
                key=normalized_key,
                incoming_rid=rid,
                committed_rid=committed_rid,
                batch_index=None,
            )

        line = {
            "op": operation,
            "key": normalized_key,
            "id": rid,
            "ts": ts,
            "prev_hash": "",
            "hash": "",
        }
        if operation != "delete":
            line["value"] = value

        prev_hash = self._tail_hash()
        line["prev_hash"] = prev_hash
        line["hash"] = line_hash(prev_hash, line)

        payload = json.dumps(
            line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ).encode("utf-8") + b"\n"

        self._path.parent.mkdir(parents=True, exist_ok=True)
        with self._path.open("ab") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())

        committed = dict(line)
        committed["replayed"] = False
        committed["committed"] = True
        return committed

    def _tail_hash(self) -> str:
        if not self._path.exists():
            return GENESIS
        raw = self._path.read_bytes()
        if not raw:
            return GENESIS
        last = raw.rstrip(b"\n").rsplit(b"\n", 1)[-1]
        line = json.loads(last.decode("utf-8"))
        return line["hash"]

    def _last_committed_for_key(self, normalized_key: str) -> dict | None:
        if not self._path.exists():
            return None
        raw = self._path.read_bytes()
        if not raw:
            return None
        last_line: dict | None = None
        for raw_line in raw.split(b"\n"):
            if not raw_line:
                continue
            line = json.loads(raw_line.decode("utf-8"))
            if line.get("key") == normalized_key:
                last_line = line
        return last_line

    def snapshot(self) -> dict:
        state: dict[str, object] = {}
        if not self._path.exists():
            return state
        raw = self._path.read_bytes()
        if not raw:
            return state
        for raw_line in raw.split(b"\n"):
            if not raw_line:
                continue
            line = json.loads(raw_line.decode("utf-8"))
            key = line["key"]
            op = line["op"]
            if op == "put":
                state[key] = line["value"]
            elif op == "delete":
                state.pop(key, None)
        return state

    def apply_batch(
        self,
        ops: list[tuple[str, str, object, str, int]]
        | tuple[tuple[str, str, object, str, int], ...],
    ) -> list[dict]:
        existing_lines = self._read_existing_lines()
        working_state: dict[str, dict] = {}
        for line in existing_lines:
            working_state[line["key"]] = line

        prev_hash = existing_lines[-1]["hash"] if existing_lines else GENESIS

        results: list[dict] = []
        new_line_bytes: list[bytes] = []

        for batch_index, op_tuple in enumerate(ops):
            operation, key, value, rid, ts = op_tuple
            normalized_key = _normalize_key(key)

            last_for_key = working_state.get(normalized_key)
            if last_for_key is not None:
                committed_rid = last_for_key.get("id")
                if committed_rid == rid:
                    replayed = dict(last_for_key)
                    replayed["replayed"] = True
                    replayed["committed"] = False
                    replayed["batch_index"] = batch_index
                    results.append(replayed)
                    continue
                raise ConflictError(
                    key=normalized_key,
                    incoming_rid=rid,
                    committed_rid=committed_rid,
                    batch_index=batch_index,
                )

            line: dict = {
                "op": operation,
                "key": normalized_key,
                "id": rid,
                "ts": ts,
                "prev_hash": prev_hash,
                "hash": "",
            }
            if operation != "delete":
                line["value"] = value

            line["hash"] = line_hash(prev_hash, line)

            working_state[normalized_key] = line
            prev_hash = line["hash"]

            new_line_bytes.append(_encode_line(line))

            committed = dict(line)
            committed["replayed"] = False
            committed["committed"] = True
            committed["batch_index"] = batch_index
            results.append(committed)

        existing_bytes = [_encode_line(line) for line in existing_lines]

        store.write_atomic(self._path, existing_bytes + new_line_bytes)

        return results

    def verify(self) -> dict:
        if not self._path.exists():
            return {"ok": True, "first_bad_index": None}
        raw = self._path.read_bytes()
        if not raw:
            return {"ok": True, "first_bad_index": None}
        expected_prev_hash: str = GENESIS
        for index, raw_line in enumerate(raw.split(b"\n")):
            if not raw_line:
                continue
            line = json.loads(raw_line.decode("utf-8"))
            if line["prev_hash"] != expected_prev_hash:
                return {"ok": False, "first_bad_index": index}
            if line_hash(line["prev_hash"], line) != line["hash"]:
                return {"ok": False, "first_bad_index": index}
            expected_prev_hash = line["hash"]
        return {"ok": True, "first_bad_index": None}

    def _read_existing_lines(self) -> list[dict]:
        existing_bytes = self._path.read_bytes() if self._path.exists() else b""
        if not existing_bytes:
            return []
        lines: list[dict] = []
        for raw_line in existing_bytes.split(b"\n"):
            if not raw_line:
                continue
            lines.append(json.loads(raw_line.decode("utf-8")))
        return lines


def _normalize_key(key: str) -> str:
    import unicodedata

    normalized = unicodedata.normalize("NFC", key)
    if normalized == "":
        raise ValueError("key must not be empty after NFC normalization")
    return normalized


def _encode_line(line: dict) -> bytes:
    return (
        json.dumps(
            line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ).encode("utf-8")
        + b"\n"
    )


__all__ = ["ConflictError", "Ledger"]


class ConflictError(Exception):
    def __init__(
        self,
        key: str,
        incoming_rid: str,
        committed_rid: str,
        batch_index: int | None,
    ) -> None:
        super().__init__(
            f"conflict on key {key!r}: incoming rid {incoming_rid!r} "
            f"does not match committed rid {committed_rid!r}"
        )
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
